import sys

def min_snooze_presses(x, hh, mm):
    target_time = hh * 60 + mm
    current_time = target_time - 60

    while True:
        current_hour = current_time // 60 % 24
        current_minute = current_time % 60

        if '7' in str(current_hour).zfill(2) or '7' in str(current_minute).zfill(2):
            return abs((target_time - current_time) // x)

        current_time -= x

if __name__ == "__main__":
    x = int(input())
    hh, mm = map(int, input().split())

    result = min_snooze_presses(x, hh, mm)

    print(result)
